import type { BankQuestion } from "@/lib/bank";

/** Banking Awareness (Banking Awareness): 114 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bank-awareness-1","question":"What is the full form of NEFT?","options":["National Electronic Funds Transfer","New Electronic Fund Transaction","National Easy Funds Transfer","Net Electronic Funds Transfer"],"answer":0,"explanation":"NEFT stands for National Electronic Funds Transfer.","difficulty":"easy"},
  {"id":"bank-awareness-2","question":"Where is the headquarters of the Reserve Bank of India?","options":["New Delhi","Kolkata","Mumbai","Chennai"],"answer":2,"explanation":"The RBI is headquartered in Mumbai.","difficulty":"easy"},
  {"id":"bank-awareness-3","question":"KYC stands for:","options":["Know Your Customer","Keep Your Cash","Know Your Credit","Key Yield Certificate"],"answer":0,"explanation":"KYC (Know Your Customer) norms verify a customer’s identity and address.","difficulty":"easy"},
  {"id":"bank-awareness-4","question":"State Bank of India was formed in 1955 from:","options":["Bank of Calcutta","Imperial Bank of India","Bank of Bombay","Allahabad Bank"],"answer":1,"explanation":"SBI was created by nationalising the Imperial Bank of India in 1955.","difficulty":"moderate"},
  {"id":"bank-awareness-5","question":"The portion of deposits that banks must keep with the RBI as cash is called:","options":["SLR","CRR","Repo rate","MSF"],"answer":1,"explanation":"CRR (Cash Reserve Ratio) is kept as cash with the RBI.","difficulty":"moderate"},
  {"id":"bank-awareness-6","question":"RTGS stands for:","options":["Real Time Gross Settlement","Rapid Transfer of Gross Savings","Real Time General Settlement","Regular Transfer Gross System"],"answer":0,"explanation":"RTGS settles large-value transfers individually and in real time.","difficulty":"moderate"},
  {"id":"bank-awareness-7","question":"What is the minimum amount for an RTGS transaction?","options":["₹10,000","₹1 lakh","₹2 lakh","₹5 lakh"],"answer":2,"explanation":"RTGS is for high-value transfers of ₹2 lakh and above; NEFT has no minimum.","difficulty":"hard"},
  {"id":"bank-awareness-8","question":"SLR (Statutory Liquidity Ratio) is the share of deposits that banks must keep in:","options":["Cash with the RBI","Liquid assets such as gold and government securities","Foreign currency","Fixed deposits"],"answer":1,"explanation":"SLR is held by the bank itself in cash, gold or approved securities; CRR is cash with the RBI.","difficulty":"hard"},
  {"id":"bank-awareness-9","question":"Which was the first bank to be nationalised in India, in 1949?","options":["State Bank of India","Reserve Bank of India","Punjab National Bank","Bank of Baroda"],"answer":1,"explanation":"The RBI was nationalised on 1 January 1949; 14 commercial banks followed in 1969.","difficulty":"hard"},
  {"id":"bank-awareness-10","question":"In which year were 14 major commercial banks nationalised?","options":["1955","1969","1980","1991"],"answer":1,"explanation":"14 banks were nationalised on 19 July 1969; six more followed in 1980.","difficulty":"very-hard"},
  {"id":"bank-awareness-11","question":"Bank deposits in India are insured by the DICGC up to:","options":["₹1 lakh","₹2 lakh","₹5 lakh","₹10 lakh"],"answer":2,"explanation":"Since February 2020, deposit insurance cover is ₹5 lakh per depositor per bank.","difficulty":"very-hard"},
  {"id":"bank-awareness-12","question":"NPCI, which operates UPI and RuPay, was set up in:","options":["2005","2008","2012","2016"],"answer":1,"explanation":"The National Payments Corporation of India was incorporated in December 2008.","difficulty":"very-hard"},
  {"id":"bank-awareness-13","question":"The headquarters of the Reserve Bank of India is in:","options":["New Delhi","Mumbai","Kolkata","Chennai"],"answer":1,"explanation":"The RBI’s central office moved from Kolkata to Mumbai in 1937.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk"},
  {"id":"bank-awareness-14","question":"NEFT stands for:","options":["National Electronic Funds Transfer","National Equity Fund Transfer","New Electronic Fund Transaction","National E-Finance Transfer"],"answer":0,"explanation":"NEFT settles transfers in half-hourly batches; RTGS is real-time for large amounts.","difficulty":"easy","source":"IBPS PO · SBI Clerk"},
  {"id":"bank-awareness-15","question":"The minimum amount that can be transferred through RTGS is:","options":["₹10,000","₹1 lakh","₹2 lakh","₹5 lakh"],"answer":2,"explanation":"RTGS is meant for high-value transfers of ₹2 lakh and above, with no upper limit.","difficulty":"moderate","source":"IBPS PO · SBI PO"},
  {"id":"bank-awareness-16","question":"The Cash Reserve Ratio (CRR) is the share of a bank’s deposits that must be kept with the:","options":["SEBI","Government of India","RBI as cash","Other banks"],"answer":2,"explanation":"CRR is held as cash with the RBI; SLR is kept by the bank itself in liquid assets.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"bank-awareness-17","question":"Under the Deposit Insurance scheme (DICGC), bank deposits are insured up to:","options":["₹1 lakh","₹2 lakh","₹5 lakh","₹10 lakh"],"answer":2,"explanation":"The cover was raised from ₹1 lakh to ₹5 lakh per depositor per bank in February 2020.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"bank-awareness-18","question":"A loan on which interest or principal has remained overdue for more than 90 days is classified as a:","options":["Standard asset","Non-performing asset","Priority-sector loan","Restructured asset"],"answer":1,"explanation":"The 90-day overdue norm defines an NPA.","difficulty":"very-hard","source":"IBPS PO · RBI Grade B"},
  {"id":"bank-awareness-19","question":"Consider: 1. SLR is kept by banks in liquid assets such as cash, gold and approved securities. 2. CRR is kept with the RBI. 3. Banks earn interest on CRR balances. Which are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The RBI pays no interest on CRR balances.","difficulty":"hard"},
  {"id":"bank-awareness-20","question":"Which of these is NOT a function of the RBI?","options":["Issuing currency notes","Banker to the government","Lender of last resort","Accepting deposits from the general public"],"answer":3,"explanation":"The RBI is a banker to banks and governments, not to the public.","difficulty":"hard"},
  {"id":"bank-awareness-21","question":"In banking, MCLR stands for:","options":["Marginal Cost of Funds based Lending Rate","Minimum Credit Lending Rate","Monetary Cost of Liquidity Ratio","Marginal Credit and Loan Rate"],"answer":0,"explanation":"MCLR replaced the base rate in April 2016 as the benchmark for loans.","difficulty":"very-hard"},
  {"id":"bank-awareness-22","question":"A cheque is valid for how long from the date written on it?","options":["1 month","3 months","6 months","1 year"],"answer":1,"explanation":"The RBI cut cheque validity from six months to three months from 1 April 2012.","difficulty":"very-hard"},
  {"id":"bank-awareness-23","question":"How many of these statements are correct? I. NABARD was set up in 1982. II. SIDBI was set up in 1990. III. EXIM Bank was set up in 1982. IV. NABARD has its headquarters in New Delhi.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. NABARD is headquartered in Mumbai.","difficulty":"very-hard"},
  {"id":"bank-awareness-24","question":"How many of these statements are correct? I. The Banking Regulation Act was passed in 1949. II. Regional Rural Banks were set up in 1975. III. Punjab National Bank is regarded as the first bank fully managed by Indians.","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"All three are correct.","difficulty":"very-hard"},
  {"id":"bank-awareness-25","question":"How many of these statements are correct? I. Banks keep SLR assets with themselves. II. CRR is kept with the RBI and earns no interest. III. The Marginal Standing Facility rate is lower than the repo rate.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. The MSF rate is set above the repo rate, as a penal window for overnight funds.","difficulty":"very-hard"},
  {"id":"bank-awareness-26","question":"The Basel III norms deal mainly with:","options":["Capital adequacy and liquidity of banks","Priority sector lending targets","Deregulation of interest rates","Know-your-customer rules"],"answer":0,"explanation":"Basel III, from the Basel Committee on Banking Supervision, sets capital, leverage and liquidity standards for banks.","difficulty":"very-hard"},
  {"id":"bank-awareness-27","question":"Under the RBI’s Prompt Corrective Action framework for banks, which indicators are tracked?","options":["Capital, asset quality and leverage","Deposits, branches and staff","CRR, SLR and repo borrowing","Inflation, GDP and fiscal deficit"],"answer":0,"explanation":"The revised PCA framework (2021) tracks capital (CRAR), asset quality (net NPA) and leverage.","difficulty":"very-hard"},
  {"id":"bank-awareness-28","question":"How many of these statements are correct? I. The RBI began operations in 1935 under the RBI Act, 1934. II. The RBI was nationalised in 1949. III. The State Bank of India was created in 1955 by taking over the Imperial Bank of India. IV. The Imperial Bank of India was formed in 1935.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The Imperial Bank was formed in 1921 by merging the three Presidency Banks.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk"},
  {"id":"bank-awareness-29","question":"Which of these is NOT a qualitative (selective) instrument of credit control used by the RBI?","options":["Margin requirements","Moral suasion","Credit rationing","Bank rate"],"answer":3,"explanation":"The bank rate, CRR, SLR and open market operations are quantitative tools that act on the total volume of credit; the other three target particular sectors or borrowers.","difficulty":"very-hard","source":"IBPS PO · RBI Grade B"},
  {"id":"bank-awareness-30","question":"The Unified Payments Interface (UPI) is operated by:","options":["Reserve Bank of India","National Payments Corporation of India","State Bank of India","Ministry of Finance"],"answer":1,"explanation":"NPCI, set up in 2008 under the guidance of the RBI and IBA, runs UPI, RuPay, IMPS and other retail payment systems.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-31","question":"The Governor of the Reserve Bank of India is appointed by the:","options":["President of India","Central Government","Parliament","Finance Commission"],"answer":1,"explanation":"Under the RBI Act, 1934 the Governor and Deputy Governors are appointed by the Central Government, normally for a term of up to five years.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-32","question":"ATM stands for:","options":["Automatic Transfer Machine","Automated Teller Machine","Any Time Money","Automated Transaction Mode"],"answer":1,"explanation":"ATM is the Automated Teller Machine; “Any Time Money” is a popular but incorrect expansion.","difficulty":"easy","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-33","question":"The IFSC code printed on a cheque consists of how many characters?","options":["9","10","11","12"],"answer":2,"explanation":"The Indian Financial System Code has 11 alphanumeric characters: the first four identify the bank, the fifth is 0, and the last six the branch.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-34","question":"The RuPay card scheme was launched by:","options":["RBI","NPCI","SBI","SEBI"],"answer":1,"explanation":"RuPay, India’s domestic card network, was launched by NPCI in 2012 as an alternative to Visa and Mastercard.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-35","question":"Which institution acts as the “lender of last resort” for banks in India?","options":["State Bank of India","Reserve Bank of India","NABARD","Ministry of Finance"],"answer":1,"explanation":"When a solvent bank cannot raise funds elsewhere, the RBI lends to it to prevent a collapse, a classic central-bank function.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-36","question":"The Pradhan Mantri Jan Dhan Yojana for financial inclusion was launched in:","options":["August 2014","January 2015","April 2016","August 2013"],"answer":0,"explanation":"PMJDY was announced on 15 August 2014 and launched on 28 August 2014 to give every household a basic savings account.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-37","question":"A payments bank in India can accept deposits from a customer up to a maximum of:","options":["₹1 lakh","₹2 lakh","₹5 lakh","₹10 lakh"],"answer":1,"explanation":"The RBI raised the per-customer deposit limit for payments banks from ₹1 lakh to ₹2 lakh in April 2021; they cannot lend.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-38","question":"Dishonour of a cheque for insufficiency of funds is an offence under which section of the Negotiable Instruments Act, 1881?","options":["Section 6","Section 31","Section 138","Section 148"],"answer":2,"explanation":"Section 138 makes cheque bouncing for insufficient funds punishable with imprisonment up to two years and/or a fine up to twice the cheque amount.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-39","question":"In the Monetary Policy Committee, if the votes are equally divided, the casting vote lies with the:","options":["Finance Minister","RBI Governor","Senior-most Deputy Governor","Chief Economic Adviser"],"answer":1,"explanation":"The six-member MPC decides by majority; the Governor, who chairs it, has a second or casting vote in case of a tie.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-40","question":"The priority sector lending target for domestic scheduled commercial banks is:","options":["18% of ANBC","32% of ANBC","40% of ANBC","50% of ANBC"],"answer":2,"explanation":"Banks must lend 40% of adjusted net bank credit to priority sectors; within this, 18% goes to agriculture and 12% to weaker sections.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-41","question":"A bank’s CASA ratio refers to the share of:","options":["Cash and short-term assets in total assets","Current and savings account deposits in total deposits","Capital and surplus in total liabilities","Credit to agriculture and small industry"],"answer":1,"explanation":"CASA deposits carry low interest, so a high CASA ratio lowers a bank’s cost of funds.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-42","question":"The Insolvency and Bankruptcy Code of India was enacted in:","options":["2013","2015","2016","2018"],"answer":2,"explanation":"The IBC, 2016 consolidated insolvency law and set a time-bound resolution process overseen by the NCLT and IBBI.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-43","question":"The Banks Board Bureau was replaced in 2022 by the:","options":["Financial Stability and Development Council","Financial Services Institutions Bureau","Bank Investment Company","Public Sector Bank Council"],"answer":1,"explanation":"The FSIB, set up in July 2022, recommends appointments of whole-time directors and heads of public-sector banks and financial institutions.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-44","question":"The RBI requires Indian banks to maintain a minimum capital-to-risk-weighted-assets ratio (CRAR), excluding the capital conservation buffer, of:","options":["8%","9%","10.5%","11.5%"],"answer":1,"explanation":"India sets the minimum CRAR at 9%, higher than the Basel III minimum of 8%; with the 2.5% capital conservation buffer the total becomes 11.5%.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-45","question":"Which banks were merged into Punjab National Bank on 1 April 2020?","options":["Dena Bank and Vijaya Bank","Oriental Bank of Commerce and United Bank of India","Syndicate Bank and Corporation Bank","Allahabad Bank and Andhra Bank"],"answer":1,"explanation":"OBC and United Bank merged into PNB; Dena and Vijaya went into Bank of Baroda (2019), Syndicate into Canara, Allahabad into Indian Bank, and Andhra and Corporation into Union Bank.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-46","question":"The RBI’s “Operation Twist” involves:","options":["Selling foreign exchange and buying gold","Simultaneous purchase of long-term and sale of short-term government securities","Raising the CRR and lowering the SLR together","Lending to banks at the MSF rate"],"answer":1,"explanation":"By buying long-dated and selling short-dated securities the RBI flattens the yield curve, lowering long-term interest rates without changing total liquidity.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-47","question":"An NPA that has remained in the sub-standard category for more than 12 months is classified as a:","options":["Standard asset","Doubtful asset","Loss asset","Special mention account"],"answer":1,"explanation":"NPA classification: sub-standard (NPA up to 12 months), doubtful (sub-standard for over 12 months) and loss (uncollectible as identified by the bank or auditors).","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-48","question":"How many of these statements about the RBI are correct? I. The RBI’s central office was first in Kolkata and moved to Mumbai in 1937. II. The RBI can have up to four Deputy Governors. III. The RBI issues all currency notes including the one-rupee note. IV. The Monetary Policy Committee was constituted in 2016.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. III is wrong: the one-rupee note is issued by the Ministry of Finance and bears the Finance Secretary’s signature; the RBI issues notes of ₹2 and above.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-49","question":"Assertion (A): When the RBI raises the repo rate, interest rates on most new floating-rate retail loans rise. Reason (R): Since October 2019 banks must link such loans to an external benchmark, most commonly the repo rate.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Under the external benchmark lending rate regime, a change in the repo rate passes through to repo-linked loans within three months, which is why retail EMIs move with policy rates.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-50","question":"Match the institution with its headquarters: 1. NABARD 2. SIDBI 3. EXIM Bank 4. National Housing Bank; a. New Delhi b. Lucknow c. Mumbai","options":["1-c, 2-b, 3-c, 4-a","1-a, 2-b, 3-c, 4-c","1-c, 2-a, 3-b, 4-c","1-b, 2-c, 3-c, 4-a"],"answer":0,"explanation":"NABARD and EXIM Bank are headquartered in Mumbai, SIDBI in Lucknow and the National Housing Bank in New Delhi.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-51","question":"A bank has net demand and time liabilities of ₹10,000 crore. If the CRR is 4.5% and the SLR is 18%, the total amount it must hold under both requirements is:","options":["₹450 crore","₹1,800 crore","₹2,250 crore","₹2,700 crore"],"answer":2,"explanation":"CRR = 4.5% × 10,000 = ₹450 crore (cash with the RBI); SLR = 18% × 10,000 = ₹1,800 crore (liquid assets with the bank); total = ₹2,250 crore.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-52","question":"Which of the following is NOT a function of the NPCI?","options":["Operating the UPI platform","Running the RuPay card network","Regulating and licensing payments banks","Operating the IMPS system"],"answer":2,"explanation":"Licensing and regulation of banks, including payments banks, is the RBI’s job; NPCI is the operator of retail payment systems such as UPI, RuPay, IMPS and BBPS.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-53","question":"How many of these statements are correct? I. RTGS has been available round the clock since December 2020. II. NEFT settles transactions in half-hourly batches. III. The per-transaction limit for IMPS is ₹5 lakh. IV. UPI was launched in 2016.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: RTGS went 24×7 on 14 December 2020, NEFT runs 48 half-hourly batches a day, the IMPS limit was raised to ₹5 lakh in 2021, and UPI was launched in April 2016.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-54","question":"Arrange in chronological order: 1. Establishment of SIDBI 2. Establishment of Regional Rural Banks 3. Launch of the Lead Bank Scheme 4. Establishment of NABARD","options":["3, 2, 4, 1","2, 3, 4, 1","3, 4, 2, 1","2, 4, 3, 1"],"answer":0,"explanation":"Lead Bank Scheme 1969 → RRBs 1975 → NABARD 1982 → SIDBI 1990.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-55","question":"Assertion (A): Payments banks cannot give loans. Reason (R): Payments banks were licensed as differentiated banks to provide small savings accounts and payment and remittance services.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The 2014 guidelines (following the Nachiket Mor committee) confine payments banks to deposits, payments and distribution of simple products; lending is outside their mandate.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-56","question":"How many of these statements are correct? I. DICGC is a wholly owned subsidiary of the RBI. II. Deposit insurance cover is ₹5 lakh per depositor per bank. III. Certificates of Deposit are issued by banks in a minimum amount of ₹5 lakh. IV. Commercial paper is a short-term instrument issued by banks.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: commercial paper is issued by corporates, primary dealers and financial institutions, not by banks, which issue certificates of deposit instead.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-57","question":"Match the banking term with its meaning: 1. Bancassurance 2. Teaser loan 3. Bank run 4. Haircut; a. Loan with a low initial rate that rises later b. Reduction in the value of an asset or claim accepted by a lender c. Selling insurance products through bank branches d. Sudden mass withdrawal of deposits","options":["1-c, 2-a, 3-d, 4-b","1-c, 2-b, 3-d, 4-a","1-d, 2-a, 3-c, 4-b","1-c, 2-a, 3-b, 4-d"],"answer":0,"explanation":"Bancassurance = insurance sold via banks; teaser loan = low initial rate; bank run = panic withdrawals; haircut = the loss a lender accepts on a claim or collateral value.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-58","question":"Which of the following rates is NOT decided by the Reserve Bank of India?","options":["Repo rate","Bank rate","MSF rate","MCLR"],"answer":3,"explanation":"The Marginal Cost of funds based Lending Rate is set by each bank from its own cost of funds; the repo, bank and MSF rates are policy rates set by the RBI/MPC.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"bank-awareness-59","question":"How many of these statements are correct? I. Tier 1 capital includes equity and disclosed reserves. II. Basel III introduced the Liquidity Coverage Ratio. III. The Basel norms are framed by the Basel Committee on Banking Supervision, hosted by the Bank for International Settlements. IV. Basel II was introduced in 1988.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: Basel I came in 1988; Basel II was issued in 2004 and Basel III after the 2008 crisis (2010).","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "bank-awareness-60", "question": "Indian currency notes of ₹2 and above are signed by the:", "options": ["Union Finance Minister", "Governor of the Reserve Bank of India", "Finance Secretary", "President of India"], "answer": 1, "explanation": "The RBI issues these notes and its Governor signs them, promising to pay the bearer. The one-rupee note is issued by the Government and signed by the Finance Secretary.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "bank-awareness-61", "question": "IMPS, the round-the-clock instant interbank transfer service, stands for:", "options": ["Immediate Payment Service", "Interbank Mobile Payment System", "Instant Money Payment Scheme", "Indian Mobile Payment Service"], "answer": 0, "explanation": "IMPS, launched by NPCI in 2010, allows instant transfers 24×7 through mobile, internet banking and ATMs.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "bank-awareness-62", "question": "Which body regulates the insurance sector in India?", "options": ["SEBI", "IRDAI", "PFRDA", "NABARD"], "answer": 1, "explanation": "The Insurance Regulatory and Development Authority of India, headquartered in Hyderabad, regulates insurance. SEBI regulates securities and PFRDA pensions.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "bank-awareness-63", "question": "A cheque that has two parallel lines drawn across its top-left corner (a crossed cheque):", "options": ["Can be paid in cash to anyone at the counter", "Can only be credited to a bank account", "Has no expiry date", "Can be issued only by companies"], "answer": 1, "explanation": "Crossing tells the bank not to pay cash over the counter; the amount must be credited to the payee’s bank account, which makes the cheque safer.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "bank-awareness-64", "question": "In November 2021, the RBI merged its separate ombudsman schemes for banks, NBFCs and digital transactions into the:", "options": ["Banking Codes and Standards Board", "Reserve Bank – Integrated Ombudsman Scheme", "Financial Stability and Development Council", "Consumer Education and Protection Cell"], "answer": 1, "explanation": "The Reserve Bank – Integrated Ombudsman Scheme, 2021 adopted “One Nation One Ombudsman”, letting customers complain through a single portal regardless of where the entity is located.", "difficulty": "moderate", "source": "RBI Assistant · IBPS PO"},
  {"id": "bank-awareness-65", "question": "Which of these payment systems is owned and operated by the Reserve Bank of India?", "options": ["UPI", "IMPS", "NEFT", "RuPay"], "answer": 2, "explanation": "NEFT and RTGS are run by the RBI. UPI, IMPS and RuPay are products of the National Payments Corporation of India.", "difficulty": "moderate", "source": "IBPS PO · SBI PO"},
  {"id": "bank-awareness-66", "question": "Under the Cheque Truncation System (CTS):", "options": ["Cheques are cleared using an electronic image instead of moving the physical cheque", "Cheques are valid for only one month", "Only bearer cheques can be cleared", "Cheques can be issued only in Hindi"], "answer": 0, "explanation": "CTS stops the physical movement of the cheque from the presenting bank to the paying bank; an image and data are sent electronically, which speeds up clearing.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "bank-awareness-67", "question": "Bharatiya Mahila Bank, set up in 2013 as a bank for women, was merged in 2017 into:", "options": ["Punjab National Bank", "State Bank of India", "Bank of Baroda", "Canara Bank"], "answer": 1, "explanation": "With effect from 1 April 2017, Bharatiya Mahila Bank and five associate banks of SBI were merged into the State Bank of India.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "bank-awareness-68", "question": "After merging with its parent Housing Development Finance Corporation in July 2023, which became India’s largest private-sector bank?", "options": ["ICICI Bank", "Axis Bank", "HDFC Bank", "Kotak Mahindra Bank"], "answer": 2, "explanation": "The HDFC–HDFC Bank merger took effect on 1 July 2023, creating by far the largest private-sector bank by assets.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "bank-awareness-69", "question": "The SARFAESI Act, which lets banks seize and sell secured assets of defaulters without going to court, was enacted in:", "options": ["1993", "2016", "2008", "2002"], "answer": 3, "explanation": "The Securitisation and Reconstruction of Financial Assets and Enforcement of Security Interest Act came in 2002. The Insolvency and Bankruptcy Code is from 2016 and the DRT Act from 1993.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "bank-awareness-70", "question": "The Bank Rate of the RBI is currently aligned with the:", "options": ["Repo rate", "Reverse repo rate", "Marginal Standing Facility rate", "Standing Deposit Facility rate"], "answer": 2, "explanation": "Since 2012 the Bank Rate has been kept equal to the MSF rate, i.e. 25 basis points above the repo rate; it is used mainly for penal rates.", "difficulty": "hard", "source": "RBI Assistant · IBPS PO"},
  {"id": "bank-awareness-71", "question": "The Kisan Credit Card scheme, to give farmers timely short-term credit, was introduced in:", "options": ["1998", "2004", "1991", "2014"], "answer": 0, "explanation": "The KCC scheme was launched in August 1998 on the recommendation of the R. V. Gupta Committee, with NABARD preparing the model scheme.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "bank-awareness-72", "question": "Under the Pradhan Mantri MUDRA Yojana (2015), the loan categories Shishu, Kishore and Tarun in ascending order of loan size are:", "options": ["Kishore, Shishu, Tarun", "Tarun, Kishore, Shishu", "Shishu, Tarun, Kishore", "Shishu, Kishore, Tarun"], "answer": 3, "explanation": "The names follow stages of growth: Shishu (smallest loans) → Kishore → Tarun (largest). A Tarun Plus category was later added above Tarun.", "difficulty": "hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "bank-awareness-73", "question": "The MICR code printed on a cheque consists of how many digits?", "options": ["6", "9", "11", "12"], "answer": 1, "explanation": "The 9-digit MICR code has 3 digits for the city, 3 for the bank and 3 for the branch. The 11-character code is the IFSC.", "difficulty": "hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "bank-awareness-74", "question": "A bank’s home-loan rate is linked to the RBI repo rate with a fixed spread of 2.75%. If the repo rate is 6.50% and the RBI cuts it by 50 basis points, the new home-loan rate is:", "options": ["9.25%", "8.75%", "8.25%", "9.00%"], "answer": 1, "explanation": "New repo = 6.50 − 0.50 = 6.00%. Loan rate = 6.00 + 2.75 = 8.75%. 100 basis points = 1 percentage point.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "bank-awareness-75", "question": "How many of these statements about cheques are correct? I. A post-dated cheque can be paid before the date written on it. II. A stale cheque is one presented after its period of validity. III. The drawer is the person who writes and signs the cheque. IV. A bearer cheque can be paid to whoever presents it.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "II, III and IV are correct. A post-dated cheque cannot be paid before its date; a cheque is stale after three months.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "bank-awareness-76", "question": "Assertion (A): A higher CASA ratio generally lowers a bank’s cost of funds. Reason (R): Current accounts pay no interest and savings accounts pay much lower interest than term deposits.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Cheap current and savings deposits reduce the average interest a bank pays on its funds, so a high CASA share improves margins. R explains A.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "bank-awareness-77", "question": "Assertion (A): Regional Rural Banks were set up to give credit to small farmers, labourers and artisans in rural areas. Reason (R): Regional Rural Banks are wholly owned by the State Governments.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true. R is false: RRB share capital is held by the Central Government (50%), the sponsor bank (35%) and the State Government (15%).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "bank-awareness-78", "question": "Match the bank with its headquarters: 1. Bank of Baroda 2. Canara Bank 3. Punjab National Bank 4. Indian Bank; a. Chennai b. Vadodara c. Bengaluru d. New Delhi", "options": ["1-b, 2-c, 3-d, 4-a", "1-c, 2-b, 3-d, 4-a", "1-b, 2-a, 3-d, 4-c", "1-d, 2-c, 3-b, 4-a"], "answer": 0, "explanation": "Bank of Baroda is headquartered in Vadodara, Canara Bank in Bengaluru, PNB in New Delhi and Indian Bank in Chennai.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "bank-awareness-79", "question": "Match the committee with its subject: 1. Narasimham Committee (1991) 2. Malegam Committee (2010) 3. Urjit Patel Committee (2014) 4. P. J. Nayak Committee (2014); a. Governance of bank boards b. Revising the monetary policy framework c. Issues in the microfinance sector d. Reform of the financial and banking system", "options": ["1-d, 2-b, 3-c, 4-a", "1-d, 2-c, 3-b, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b"], "answer": 1, "explanation": "Narasimham led banking-sector reforms, Malegam looked at microfinance after the Andhra Pradesh crisis, Urjit Patel recommended inflation targeting, and P. J. Nayak reviewed governance of bank boards.", "difficulty": "very-hard", "source": "RBI Assistant · IBPS PO"},
  {"id": "bank-awareness-80", "question": "Which of the following is NOT a negotiable instrument under the Negotiable Instruments Act, 1881?", "options": ["Promissory note", "Bill of exchange", "Cheque", "Fixed deposit receipt"], "answer": 3, "explanation": "Section 13 names promissory notes, bills of exchange and cheques as negotiable instruments. A fixed deposit receipt cannot be transferred by endorsement and delivery.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "bank-awareness-81", "question": "Arrange in chronological order: 1. Setting up of NPCI 2. Launch of UPI 3. Launch of RuPay 4. Introduction of NEFT", "options": ["4, 1, 2, 3", "1, 4, 3, 2", "4, 1, 3, 2", "4, 3, 1, 2"], "answer": 2, "explanation": "NEFT began in 2005, NPCI was set up in 2008, RuPay was launched in 2012 and UPI in 2016.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "bank-awareness-82", "question": "How many of these statements about priority sector lending are correct? I. The overall target for domestic scheduled commercial banks is 40% of ANBC or credit-equivalent of off-balance-sheet exposure, whichever is higher. II. Agriculture is a priority sector. III. Education loans to individuals can qualify as priority sector lending. IV. Working-capital loans to large corporates are classified as priority sector lending.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Loans to large corporates are not priority sector; the scheme directs credit to agriculture, MSMEs, education, housing, weaker sections and similar areas.", "difficulty": "very-hard", "source": "RBI Assistant · IBPS PO"},
  {"id": "bank-awareness-83", "question": "₹10,000 is deposited at 10% per annum compounded half-yearly. The interest earned in one year is:", "options": ["₹1,000", "₹1,025", "₹1,050", "₹1,100"], "answer": 1, "explanation": "Rate per half-year = 5%, periods = 2. Amount = 10,000 × 1.05² = ₹11,025, so interest = ₹1,025 (₹25 more than simple interest).", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "bank-awareness-84", "question": "Which of the following is NOT a public sector bank as categorised by the RBI?", "options": ["Bank of India", "UCO Bank", "IDBI Bank", "Bank of Maharashtra"], "answer": 2, "explanation": "The RBI recategorised IDBI Bank as a private-sector bank from January 2019 after LIC acquired a controlling stake, even though the Government and LIC together hold most of its shares.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "bank-awareness-85", "question": "In banking, NACH, the system used for bulk payments such as salaries and EMI debits, stands for:", "options": ["National Automated Clearing House", "National Advance Credit House", "Net Automated Cheque Handling", "National Account Clearing Hub"], "answer": 0, "explanation": "NACH is run by the NPCI and handles high-volume, repetitive credits and debits such as salaries, dividends, subsidies and loan EMIs. It replaced the older ECS system.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk · IBPS RRB"},
  {"id": "bank-awareness-86", "question": "AePS, which lets a customer withdraw cash at a micro-ATM using fingerprint authentication, stands for:", "options": ["Account Enabled Pay Scheme", "Automated e-Payment Service", "Aadhaar e-Purse System", "Aadhaar Enabled Payment System"], "answer": 3, "explanation": "The Aadhaar Enabled Payment System, run by the NPCI, uses the Aadhaar number and biometrics to authenticate basic banking transactions through business correspondents.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk · IBPS RRB"},
  {"id": "bank-awareness-87", "question": "In discussions of the RBI’s digital rupee, CBDC stands for:", "options": ["Central Bank Digital Currency", "Certified Bank Deposit Certificate", "Central Board of Digital Credit", "Commercial Bank Digital Cash"], "answer": 0, "explanation": "A CBDC is legal tender issued by a central bank in digital form; in India it is called the e₹ and is a liability of the RBI, just like a currency note.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk · IBPS RRB"},
  {"id": "bank-awareness-88", "question": "BBPS, the interoperable platform for paying electricity, gas, DTH and other bills, stands for:", "options": ["Bank Bill Processing Service", "Bharat Banking Payment Switch", "Basic Billing and Payment Scheme", "Bharat Bill Payment System"], "answer": 3, "explanation": "The Bharat Bill Payment System is run by NPCI Bharat BillPay Ltd under RBI authorisation, so one can pay any participating biller through any bank or app.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "bank-awareness-89", "question": "A ‘Nostro account’ is:", "options": ["A dormant account in which no transaction has taken place for 2 years", "An account an Indian bank keeps with a foreign bank, in that country’s currency", "An account opened by a non-resident Indian in rupees", "An account a foreign bank keeps with an Indian bank in rupees"], "answer": 1, "explanation": "Nostro means ‘ours with you’: for example, SBI’s US-dollar account with a bank in New York. The reverse, a foreign bank’s rupee account with an Indian bank, is a Vostro account.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-90", "question": "SWIFT, the global messaging network that banks use for cross-border payment instructions, has its headquarters in:", "options": ["Switzerland", "United States", "Belgium", "United Kingdom"], "answer": 2, "explanation": "The Society for Worldwide Interbank Financial Telecommunication is a cooperative based at La Hulpe, Belgium. The Basel Committee on Banking Supervision, in contrast, sits at Basel in Switzerland.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "bank-awareness-91", "question": "The CIBIL score, used by lenders to judge a borrower’s creditworthiness, ranges from:", "options": ["1 to 10", "100 to 1,000", "0 to 100", "300 to 900"], "answer": 3, "explanation": "TransUnion CIBIL scores run from 300 to 900; scores above about 750 are generally considered good. The score is built from the person’s past repayment record and credit usage.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "bank-awareness-92", "question": "A Basic Savings Bank Deposit Account (BSBDA) is distinguished by:", "options": ["Being available only to senior citizens", "No requirement to maintain any minimum balance", "A higher rate of interest than other savings accounts", "A minimum balance of ₹10,000"], "answer": 1, "explanation": "RBI rules require BSBDAs to have no minimum balance, with free basic services such as an ATM card and at least four withdrawals a month. Jan Dhan accounts are opened as BSBDAs.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk · IBPS RRB"},
  {"id": "bank-awareness-93", "question": "A zero-coupon bond is one that:", "options": ["Is issued at a discount and redeemed at face value, paying no periodic interest", "Can be bought only by banks", "Pays interest every month", "Has no maturity date"], "answer": 0, "explanation": "The investor’s return is the difference between the discounted issue price and the face value paid at maturity. A bond with no maturity date is a perpetual bond.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-94", "question": "A Certificate of Deposit issued by a scheduled commercial bank can have a maturity of:", "options": ["1 day to 90 days", "5 years to 10 years", "7 days to 1 year", "1 year to 3 years"], "answer": 2, "explanation": "Banks may issue CDs for 7 days to one year, while all-India financial institutions may issue them for 1 to 3 years. Commercial paper, issued by companies, also runs from 7 days to one year.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-95", "question": "Deposits left unclaimed in a bank account for 10 years or more are transferred to the:", "options": ["Consolidated Fund of India", "Prime Minister’s National Relief Fund", "Depositor Education and Awareness Fund maintained by the RBI", "DICGC reserve"], "answer": 2, "explanation": "Since 2014, banks transfer such balances to the RBI’s DEA Fund, but the depositor or legal heir can claim the money back from the bank at any time, with interest where applicable.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-96", "question": "UDGAM, launched by the RBI in August 2023, is a portal that lets people:", "options": ["File complaints against banks", "Check their credit score", "Apply for new bank licences", "Search for their unclaimed deposits across several banks in one place"], "answer": 3, "explanation": "UDGAM (Unclaimed Deposits – Gateway to Access inforMation) brings together data on unclaimed deposits from participating banks. Complaints go to the Integrated Ombudsman scheme instead.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "bank-awareness-97", "question": "A bank has gross NPAs of ₹2,500 crore and has made provisions of ₹1,500 crore against them. Its provision coverage ratio is:", "options": ["60%", "166.7%", "37.5%", "40%"], "answer": 0, "explanation": "Provision coverage ratio = provisions ÷ gross NPAs × 100 = 1,500 ÷ 2,500 × 100 = 60%. A higher PCR means the bank is better cushioned against loan losses.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-98", "question": "From 2020–21, the accounting year of the Reserve Bank of India runs from:", "options": ["July to June", "April to March", "January to December", "October to September"], "answer": 1, "explanation": "The RBI earlier followed a July–June year; it switched to April–March to match the government’s financial year, with July 2020 to March 2021 as a nine-month transition year.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-99", "question": "Which of these banks was NOT on the RBI’s list of Domestic Systemically Important Banks (D-SIBs) released in 2024?", "options": ["Axis Bank", "ICICI Bank", "State Bank of India", "HDFC Bank"], "answer": 0, "explanation": "The D-SIB list has three banks: SBI, HDFC Bank and ICICI Bank, which must hold extra Common Equity Tier 1 capital because their failure would hurt the whole system. Axis Bank is not on the list.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "bank-awareness-100", "question": "The RBI’s pilot of the retail digital rupee (e₹-R) began on:", "options": ["1 December 2022", "1 November 2022", "1 April 2023", "15 August 2022"], "answer": 0, "explanation": "The retail pilot began on 1 December 2022 in select cities. The wholesale pilot (e₹-W), for settling government securities trades, had started earlier, on 1 November 2022.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-101", "question": "Sovereign Gold Bonds, issued by the RBI on behalf of the Government of India, have a tenure and fixed interest rate of:", "options": ["10 years and 3% a year", "3 years and no interest", "8 years, with an exit option from the fifth year, and 2.5% a year", "5 years and 1.5% a year"], "answer": 2, "explanation": "SGBs run for 8 years with premature redemption allowed after the fifth year, and pay 2.5% a year on the issue price, half-yearly, on top of any rise in the gold price.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "bank-awareness-102", "question": "A ‘garnishee order’ received by a bank is:", "options": ["A court order directing the bank to hold or pay over money in a customer’s account to satisfy a creditor’s claim", "A customer’s instruction to stop payment of a cheque", "An RBI order to cancel the bank’s licence", "A tax refund order from the Income Tax Department"], "answer": 0, "explanation": "Under the Civil Procedure Code, a court can attach a judgment-debtor’s balance with a bank (the garnishee) so that it is paid to the creditor. A stop-payment instruction comes from the customer, not a court.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-103", "question": "How many of these statements about the Banking Laws (Amendment) Act, 2025 are correct? I. It allows up to four nominees for a bank deposit account. II. It raises the threshold for ‘substantial interest’ in a company from ₹5 lakh to ₹2 crore. III. It extends the maximum tenure of directors of cooperative banks (other than the chairman and whole-time director) from 8 to 10 years. IV. It nationalised IDBI Bank.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The Act nationalised no bank; IDBI Bank has been categorised by the RBI as a private-sector bank since January 2019.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-104", "question": "How many of these statements about Regional Rural Banks are correct? I. The first RRB, Prathama Bank in Moradabad, was sponsored by Syndicate Bank. II. The Centre, the sponsor bank and the State government hold their shares in the ratio 50 : 35 : 15. III. After the ‘One State, One RRB’ amalgamation that took effect on 1 May 2025, there are 28 RRBs. IV. RRBs are governed by the Regional Rural Banks Act, 1976.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. RRBs began on 2 October 1975 under an ordinance replaced by the 1976 Act, and the 2025 amalgamation of 26 RRBs brought their number down from 43 to 28.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk · IBPS RRB"},
  {"id": "bank-awareness-105", "question": "A bank has gross advances of ₹50,000 crore, gross NPAs of ₹2,500 crore and provisions of ₹1,500 crore. Its net NPA ratio is about:", "options": ["2.06%", "3.00%", "2.00%", "5.00%"], "answer": 0, "explanation": "Net NPA = 2,500 − 1,500 = ₹1,000 crore; net advances = 50,000 − 1,500 = ₹48,500 crore. Net NPA ratio = 1,000 ÷ 48,500 × 100 ≈ 2.06%. Dividing by gross advances gives the trap 2%, and 5% is the gross NPA ratio.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-106", "question": "Match the money-market instrument with its tenure: 1. Call money 2. Notice money 3. Term money 4. Treasury bill; a. Up to 364 days, issued for the government b. 15 days to one year c. 2 to 14 days d. Overnight (one day)", "options": ["1-d, 2-c, 3-a, 4-b", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-b, 4-a", "1-d, 2-b, 3-c, 4-a"], "answer": 2, "explanation": "Call money is borrowed overnight, notice money for 2–14 days and term money for 15 days to a year; Treasury bills are issued by the RBI for the government in 91-, 182- and 364-day maturities.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-107", "question": "Arrange in chronological order: 1. Demonetisation of the old ₹500 and ₹1,000 notes 2. Launch of the Pradhan Mantri Jan Dhan Yojana 3. Merger of ten public sector banks into four taking effect 4. RBI’s in-principle approval to eleven payments banks", "options": ["4, 2, 1, 3", "2, 4, 3, 1", "2, 1, 4, 3", "2, 4, 1, 3"], "answer": 3, "explanation": "Jan Dhan was launched in August 2014, payments-bank approvals came in August 2015, demonetisation was announced on 8 November 2016, and the big bank merger took effect on 1 April 2020.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "bank-awareness-108", "question": "Assertion (A): In a pledge, the lender takes possession of the goods offered as security. Reason (R): In hypothecation, the borrower keeps possession of the goods offered as security.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 1, "explanation": "Both are true, but R describes a different kind of charge and does not explain A. In a pledge, such as a gold loan, the lender holds the goods; in hypothecation, such as a car loan, the borrower keeps and uses the asset.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-109", "question": "How many of these statements about the RBI’s Financial Inclusion Index are correct? I. It was first published in 2021. II. Its value ranges from 0 to 100. III. It is built from three sub-indices: Access, Usage and Quality. IV. It is published every quarter.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct; Usage carries the largest weight (45%), then Access (35%) and Quality (20%). IV is wrong: the index is published once a year, in July.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-110", "question": "Which of the following is NOT a money-market instrument?", "options": ["Certificate of deposit", "Treasury bill", "Commercial paper", "10-year dated government security"], "answer": 3, "explanation": "The money market deals in instruments of up to one year. A 10-year dated government security belongs to the capital (debt) market, even though, like a T-bill, it is issued by the government.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-111", "question": "A depositor holds ₹4 lakh in a savings account and ₹3 lakh in a fixed deposit, both in his own name, in Bank X, and ₹2 lakh in Bank Y. If both banks fail, the maximum total amount he can receive under DICGC deposit insurance is:", "options": ["₹7 lakh", "₹9 lakh", "₹10 lakh", "₹5 lakh"], "answer": 0, "explanation": "Cover is ₹5 lakh per depositor per bank, counting all his accounts in the same capacity together. From Bank X he gets ₹5 lakh of his ₹7 lakh, and from Bank Y the full ₹2 lakh, so ₹7 lakh in all.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "bank-awareness-112", "question": "Assertion (A): Small finance banks must ensure that at least 50% of their loan portfolio consists of loans of up to ₹25 lakh. Reason (R): Small finance banks were set up to take banking to small business units, small and marginal farmers, micro industries and the unorganised sector.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The small-loan requirement exists precisely to serve the financial-inclusion purpose for which these banks were licensed, so R explains A. SFBs also face a higher priority-sector target than universal banks.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RBI Grade B"},
  {"id": "bank-awareness-113", "question": "How many of these statements are correct? I. The minimum paid-up capital for a payments bank is ₹100 crore. II. The minimum paid-up capital for a new small finance bank under the 2019 on-tap guidelines is ₹200 crore. III. Payments banks can issue debit cards. IV. Payments banks can issue credit cards.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Payments banks cannot lend at all, so they cannot issue credit cards, though they can issue ATM or debit cards.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "bank-awareness-114", "question": "Match the payment product with its feature: 1. UPI 123PAY 2. UPI Lite 3. BHIM 4. FASTag; a. Electronic toll payment using RFID b. NPCI’s own UPI app c. Small-value payments from an on-device balance without a UPI PIN d. UPI payments from feature phones", "options": ["1-d, 2-c, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a", "1-b, 2-c, 3-d, 4-a", "1-c, 2-d, 3-b, 4-a"], "answer": 1, "explanation": "UPI 123PAY (2022) brings UPI to feature phones, UPI Lite allows quick small payments from a wallet-like balance on the device, BHIM is the NPCI’s app (2016), and FASTag pays tolls through an RFID sticker.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
];

export default questions;
